using System;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using OneWay.Battle3D;
public static class ConnectGoldenPackageSlash{
public static string Run(){if(Application.isPlaying)throw new Exception("Edit mode required");const string path="Assets/3DBattle/Boss2/GoldenSlashVFX/B2GoldenSlash.prefab";var edit=PrefabUtility.LoadPrefabContents(path);
try{var distortion=edit.transform.Find("Golden Crescent and Trails/Slash Distortion");if(distortion!=null)distortion.gameObject.SetActive(false);PrefabUtility.SaveAsPrefabAsset(edit,path);}finally{PrefabUtility.UnloadPrefabContents(edit);}
var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(path);var deps=AssetDatabase.GetDependencies(path,true);if(deps.Any(p=>p.StartsWith("Assets/Free Slash VFX/")))throw new Exception("Original package dependency remains");
foreach(var mat in deps.Where(p=>p.EndsWith(".mat")).Select(AssetDatabase.LoadAssetAtPath<Material>))if(mat.shader==null||ShaderUtil.ShaderHasError(mat.shader))throw new Exception("Shader error: "+mat.name);
var g=UnityEngine.Object.Instantiate(prefab);g.hideFlags=HideFlags.HideAndDontSave;
try{var flight=g.AddComponent<B2SlashFlight>();flight.Initialize(Vector3.forward,20,2,.2f);var advance=typeof(B2SlashFlight).GetMethod("Advance",BindingFlags.Instance|BindingFlags.NonPublic);var start=g.transform.position;advance.Invoke(flight,new object[]{.1f});if(Vector3.Distance(start,g.transform.position)>.0001f)throw new Exception("Delay failed");advance.Invoke(flight,new object[]{.15f});if(Mathf.Abs(g.transform.position.z-start.z-1)>.0001f)throw new Exception("Speed failed");foreach(var ps in g.GetComponentsInChildren<ParticleSystem>()){ps.Simulate(.2f,false,true);if(!ps.main.playOnAwake)throw new Exception("Particle not enabled at spawn");}}
finally{UnityEngine.Object.DestroyImmediate(g);}
var emitter=UnityEngine.Object.FindObjectsByType<B2SwordSlash>(FindObjectsInactive.Include,FindObjectsSortMode.None).Single(e=>e.gameObject.scene.path=="Assets/Scenes/3DBattleScene.unity");Undo.RecordObject(emitter,"Connect package golden slash");emitter.slashPrefab=prefab;EditorUtility.SetDirty(emitter);PrefabUtility.RecordPrefabInstancePropertyModifications(emitter);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(emitter.gameObject.scene);EditorSceneManager.SaveScene(emitter.gameObject.scene);
return "PASS: independent assets, all shaders valid, delayed launch and speed verified; boss linked to "+path+"; existing speed="+emitter.travelSpeed+", delay="+emitter.launchDelay+", heightMultiplier="+emitter.heightMultiplier;
}}
